  it.each(examples)("replays a committed pre-gate admission of %s content from the local journal without reselecting it", async (_kind, caseId) => {
    const old = fixture(caseId), f = await rig(old.state);
    const coordinator = new CloudSyncCoordinator({ ...f.runtime, scope: f.scope, clock: f.clock, enabled: true });
    expect(await coordinator.open()).toBe(true); expect(await coordinator.startWriter()).toBe(true); expect(coordinator.resume()).toBe(true);
    const loaded = await loadCloudEvidenceCheckpoint({ ...f.copy, expectedRevision: "57", expectedCampaignId: old.state.campaignId, expectedBaselineId: f.copy.baselineId });
    const key = cloudCampaignStorageKey(f.scope), owner = "pre-gate.writer";
    const head = await bindJournal(f.cache.journal!, key, owner, { checkpoint: loaded.checkpoint, campaign: loaded.campaign, source: loaded.source,
      confirmed: f.copy, usageQuestions: [], writerGeneration: coordinator.journalWriterGeneration,
      snapshotPolicy: { lineage: { ...loaded.snapshotLineage!, parents: [f.copy.snapshot.uncompressedSha256] } } }, cloudCodec);
    const drain = new LocalJournalDrain(f.cache.journal!, key, owner, head.highWater, error => { throw error; });
    const committed = applyGameEvidenceCommand(loaded.checkpoint, old.admission, preGate);
    expect(committed.state.operationReceipts[old.admission.operationId]).toMatchObject({ status: "applied" });
    drain.accept({ delta: gameEvidenceDelta(loaded.checkpoint, committed.checkpoint), campaign: loaded.campaign, usageQuestions: [], writerGeneration: coordinator.journalWriterGeneration });
    expect(await drain.drain()).toBe(true); drain.stop(); coordinator.dispose();
    const stored = await f.cache.journal!.read(key);
    expect(stored!.rows).toHaveLength(1);
    const frozen = committed.state.encounters[encounterId]!.frozenCase;
    const session = await CloudGameSession.create(await f.open(), undefined, undefined, { operational: false });
    try {
      expect(session.state.encounters[encounterId]!.frozenCase).toEqual(frozen);
      expect(session.state.operationReceipts[old.admission.operationId]).toEqual(committed.state.operationReceipts[old.admission.operationId]);
      expect(session.state.learningHistories[old.conceptId]).toEqual(committed.state.learningHistories[old.conceptId]);
      expect(session.state.campaignId).toBe(old.state.campaignId); expect(session.syncView.failure).toBeNull();
      await finish(session, old.conceptId, frozen);
      const restored = await prepareJournal(f.cache.journal!, key, cloudCodec, { local: true, encode: false });
      expect(restored!.state).toEqual(session.state);
    } finally { session.dispose(); }
  });
});

import { createHash } from "node:crypto";
import { existsSync, readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import {
  ANSWER_CHOICE_TIMING_REGISTRY,
  QUESTION_BANK_BATCH2B_REVISIONS,
  QUESTION_BANK_BATCH2B_ROUND2_REVISIONS,
  QUESTION_BANK_BATCH2B_ROUND2_SOURCE_RELEASE as source,
  SYNTHETIC_CLINICAL_RELEASE as live,
} from "./index";
import { QUESTION_SHIP_MANIFEST as manifest, type QuestionShipManifest } from "./question-ship-manifest";
import { QUESTION_FLAGS2_ROUND3_SOURCE_RELEASE as acceptedFlags2 } from "./question-flags2-round3-20261105";

const read = (path: string): string => readFileSync(new URL("../../../" + path, import.meta.url), "utf8");
const sha = (text: string): string => createHash("sha256").update(text).digest("hex");
const intake = JSON.parse(read("tools/question-quality/fixtures/batch2b-acceptance-before-20261105.json")) as {
  release: typeof live;
  manifest: QuestionShipManifest;
  packet: Array<{ id: string; caseId: string; nodeId: string; after: { variantId: string } }>;
  review: Array<{ id: string; verdict: string }>;
};
const changes = JSON.parse(read("tools/question-quality/batch2b-acceptance-changes-20261105.json")) as {
  acceptedRows: QuestionShipManifest["accepted"];
  holds: Array<{ id: string; classification: string; accepted: boolean; itemEdited: boolean; claimIds: string[] }>;
  digestReconciliation: {
    count: number; captures: number;
    rows: Array<{ capture: string; path: string; expected: string; actual: string }>;
    files: Array<{ path: string; beforeSha256: string; currentSha256: string }>;
  };
};
const acceptedIds = [
  "B2B01", "B2B02", "B2B06", "B2B08", "B2B09", "B2B10", "B2B17", "B2B21",
  "B2B23", "B2B24", "B2B25", "B2B30", "B2B33", "B2B39", "B2B40", "B2B42",
];
const heldIds = ["B2B32", "F13"];
const ownRows = manifest.accepted.filter(row => row.sourceView === "batch2b-round2");
const saved = (value: unknown): string | undefined => JSON.stringify(value);
const nodeFor = (release: typeof live, caseId: string, nodeId: string) =>
  release.cases.find(cs => cs.id === caseId)!.decisionNodes.find(node => node.id === nodeId)!;

describe("batch 2b manager-directed exact-version acceptance", () => {
  it("accepts exactly the sixteen unconditional PASS tuples and their reviewed headers", () => {
    expect(ownRows.map(row => row.acceptanceId).sort()).toEqual(acceptedIds.slice().sort());
    expect(ownRows).toEqual(changes.acceptedRows);
    expect(new Set(ownRows.map(row => row.caseId)).size).toBe(16);
    for (const row of ownRows) {
      expect(intake.review.find(item => item.id === row.acceptanceId)?.verdict).toBe("PASS");
      expect(row.decision).toBe("docs/research/question-bank-batch2b-manager-decision-20261105.md");
      expect(manifest.headerSources[row.caseId]).toBe("batch2b-round2");
    }
  });

  it.each(acceptedIds)("projects %s exactly, with its historical timing tuple and draft review status", id => {
    const row = ownRows.find(row => row.acceptanceId === id)!;
    const current = live.cases.find(cs => cs.id === row.caseId)!;
    const authored = source.cases.find(cs => cs.id === row.caseId)!;
    const node = nodeFor(live, row.caseId, row.nodeId);
    expect(node).toEqual(nodeFor(source, row.caseId, row.nodeId));
    expect(node).toMatchObject({ questionVariantId: row.questionVariantId, primaryConceptId: row.conceptId, shuffleAnswers: true });
    expect(current.presentation).toBe(authored.presentation);
    expect(current.chiefComplaint).toBe(authored.chiefComplaint);
    expect(current.approvedInstantiationProfiles).toEqual(authored.approvedInstantiationProfiles);
    const revision = [...QUESTION_BANK_BATCH2B_REVISIONS, ...QUESTION_BANK_BATCH2B_ROUND2_REVISIONS]
      .find(candidate => candidate.questionVariantId === row.questionVariantId)!;
    expect(revision.question.reviewStatus).toBe("needs_clinician_review");
    expect(revision.question.lastClinicianReview).toBeNull();
    const timings = ANSWER_CHOICE_TIMING_REGISTRY.filter(timing => timing.caseId === row.caseId &&
      timing.nodeId === row.nodeId && timing.questionVariantId === row.questionVariantId);
    expect(timings).toHaveLength(1);
    const classification = timings[0]!.classification;
    if (classification.kind === "test_choices") {
      expect(classification.choices).toHaveLength(node.answerChoices.length);
      for (const choice of node.answerChoices) {
        expect(classification.choices.find(timing => timing.choiceId === choice.id)?.choiceLabel).toBe(choice.label);
      }
    }
  });

  it("keeps both source-held PASS keys live without editing or accepting either draft", () => {
    expect(changes.holds.map(row => row.id).sort()).toEqual(heldIds.slice().sort());
    for (const hold of changes.holds) {
      expect(hold).toMatchObject({ classification: "hold_on_key", accepted: false, itemEdited: false });
      expect(hold.claimIds.length).toBeGreaterThan(0);
      expect(ownRows.some(row => row.acceptanceId === hold.id)).toBe(false);
      const packet = intake.packet.find(row => row.id === hold.id)!;
      expect(saved(nodeFor(live, packet.caseId, packet.nodeId)))
        .toBe(saved(nodeFor(intake.release, packet.caseId, packet.nodeId)));
    }
  });

  it("parks all twenty-two REVISE drafts, preserving fallback except the later exact flags2 whole-case acceptance", () => {
    const revise = intake.review.filter(row => row.verdict === "REVISE");
    expect(revise).toHaveLength(22);
    for (const item of revise) {
      const packet = intake.packet.find(row => row.id === item.id)!;
      if(manifest.replacements.some(r=>r.replaces===packet.caseId)){
        expect(live.cases.find(c=>c.id===packet.caseId)).toEqual(acceptedFlags2.cases.find(c=>c.id===packet.caseId));
      }else{
        expect(saved(nodeFor(live, packet.caseId, packet.nodeId)))
          .toBe(saved(nodeFor(intake.release, packet.caseId, packet.nodeId)));
      }
      expect(manifest.accepted.some(row => row.caseId === packet.caseId && row.nodeId === packet.nodeId &&
        row.questionVariantId === packet.after.variantId)).toBe(false);
    }
    const g03 = intake.packet.find(row => row.id === "B2B36")!;
    expect(nodeFor(live, g03.caseId, g03.nodeId).questionVariantId)
      .toBe("question.palpable-breast.negative-mammogram-targeted-us.v1.r4");
  });

  it("preserves every historical legacy binding and existing non-N2 acceptance", () => {
    expect(manifest.legacyBindings).toEqual(intake.manifest.legacyBindings);
    for (const old of intake.manifest.accepted.filter(row => !row.acceptanceId.startsWith("review.n2."))) {
      expect(manifest.accepted.find(row => row.acceptanceId === old.acceptanceId)).toEqual(old);
    }
    for (const old of intake.release.concepts) {
      expect(live.concepts.find(row => row.id === old.id)).toEqual(old);
    }
    expect(live.cases).toHaveLength(intake.release.cases.length);
  });

  it("composes B2B24 with the exact old second node and gate, without importing a neighboring draft", () => {
    const row = ownRows.find(row => row.acceptanceId === "B2B24")!;
    const current = live.cases.find(cs => cs.id === row.caseId)!;
    const old = intake.release.cases.find(cs => cs.id === row.caseId)!;
    expect(current.decisionNodes).toHaveLength(2);
    expect(current.decisionNodes[0]).toEqual(nodeFor(source, row.caseId, row.nodeId));
    expect(saved(current.decisionNodes[1])).toBe(saved(old.decisionNodes[1]));
    expect(saved(current.decisionNodes[0]!.resultGateAfter)).toBe(saved(old.decisionNodes[0]!.resultGateAfter));
    const exhibit = current.decisionNodes[0]!.exhibit!;
    expect(exhibit.kind).toBe("image");
    if (exhibit.kind === "image") expect(existsSync(new URL("../../../apps/player/public/" + exhibit.assetPath, import.meta.url))).toBe(true);
    const preview = JSON.parse(read("docs/research/question-bank-batch2b-composed-preview-20261105.json")) as {
      label: string; acceptedCount: number; mixedCases: Array<{ caseId: string; sequenceLimitation: string }>;
      cases: Array<{ caseId: string; nodes: Array<{ Options: string[] }> }>;
    };
    expect(preview.label).toContain("key shown first for review only");
    expect(preview.acceptedCount).toBe(16);
    expect(preview.mixedCases).toHaveLength(1);
    expect(preview.mixedCases[0]!.caseId).toBe(row.caseId);
    expect(preview.mixedCases[0]!.sequenceLimitation).toContain("rehearsed/easy");
    expect(preview.cases.find(cs => cs.caseId === row.caseId)!.nodes.every(node => node.Options[0]!.startsWith("**KEY:** "))).toBe(true);
  });

  it("reconciles only the three receipt-authorized scalar hashes in the two captures", () => {
    expect(changes.digestReconciliation.count).toBe(3);
    expect(changes.digestReconciliation.captures).toBe(2);
    expect(changes.digestReconciliation.rows).toHaveLength(3);
    for (const capture of changes.digestReconciliation.files) {
      const current = read(capture.path);
      expect(sha(current)).toBe(capture.currentSha256);
      let reversed = current;
      for (const row of changes.digestReconciliation.rows.filter(row => row.capture === capture.path)) {
        const needle = JSON.stringify(row.path) + ": " + JSON.stringify(row.actual);
        expect(reversed.split(needle)).toHaveLength(2);
        reversed = reversed.replace(needle, JSON.stringify(row.path) + ": " + JSON.stringify(row.expected));
        expect(sha(read(row.path))).toBe(row.actual);
      }
      // Byte-for-byte reversal proves that no other capture field was altered.
      expect(sha(reversed)).toBe(capture.beforeSha256);
    }
  });
});

import { describe, expect, it } from "vitest";
import {
  getPilotChartReviewByCaseId,
  PILOT_CLINICAL_RELEASE,
  PILOT_REGISTRY,
} from "./pilot-content";
import { materializePilotEncounter } from "./pilot-generator";

const PILOT_FAMILY_IDS = [
  "traumatic_laceration",
  "cutaneous_abscess",
  "symptomatic_cholelithiasis",
  "inguinal_hernia",
  "acute_appendicitis",
] as const;

// These exact clinician-approved variants cannot be reworded to balance choice
// length without a new owner review. Keep this exception list narrow and prove
// every entry remains an actual length violation.
const IMMUTABLE_APPROVED_LENGTH_EXCEPTIONS = new Set([
  "question.choledochal-cyst.type-iva.2c.v1",
  "question.choledochal-cyst.type-iva.2d.v1",
  "question.anal-hsil.hpv.3a.v1",
  "question.anal-hsil.hpv.3b.v1",
  "question.anal-hsil.hpv.3c.v1",
  "question.anal-hsil.hpv.3d.v1",
  "question.men2a.2d.v1",
  "question.men2a.3c.v1",
  "question.men2a.3d.v1",
  "question.graves-rai-appropriate-candidate.v2",
  "question.graves-rai-lactation-contraindication.v1",
  "question.graves-rai-pregnancy-contraindication.v1",
]);

function generatedForEveryTemplate(seed = "pilot-test-seed") {
  return PILOT_REGISTRY.encounterTemplates.map((template) =>
    materializePilotEncounter(PILOT_REGISTRY, template.id, seed),
  );
}

describe("five-diagnosis pilot registry", () => {
  it("does not make the keyed answer uniquely longest in the runtime release", () => {
    const seenQuestionVariantIds = new Set<string>();
    const violations = PILOT_CLINICAL_RELEASE.cases.flatMap((clinicalCase) =>
      clinicalCase.decisionNodes.flatMap((node) => {
        if (clinicalCase.id.startsWith("case.l2.")) return [];
        if (seenQuestionVariantIds.has(node.questionVariantId)) {
          return [];
        }
        seenQuestionVariantIds.add(node.questionVariantId);
        const correct = node.answerChoices.find((choice) => choice.isCorrect);
        const longestDistractor = Math.max(
          ...node.answerChoices
            .filter((choice) => !choice.isCorrect)
            .map((choice) => choice.label.length),
        );
        return correct && correct.label.length > longestDistractor
          ? [
              {
                questionVariantId: node.questionVariantId,
                correctLength: correct.label.length,
                longestDistractor,
              },
            ]
          : [];
      }),
    );

    expect(
      violations.map((violation) => violation.questionVariantId).sort(),
    ).toEqual([...IMMUTABLE_APPROVED_LENGTH_EXCEPTIONS].sort());
  });

  it("contains exactly the five requested families with Level 0 and Level 1 phenotypes", () => {
    expect(
      PILOT_REGISTRY.diagnosisFamilies.map((family) => family.id).sort(),
    ).toEqual([...PILOT_FAMILY_IDS].sort());

    for (const family of PILOT_REGISTRY.diagnosisFamilies) {
      const tiers = PILOT_REGISTRY.phenotypes
        .filter((phenotype) => phenotype.diagnosisFamilyId === family.id)
        .map((phenotype) => phenotype.educationalTier);
      expect(tiers).toContain(0);
      expect(tiers).toContain(1);
    }
  });

  it("provides at least three concepts and two independently identified variants per family", () => {
    expect(PILOT_REGISTRY.concepts).toHaveLength(15);
    for (const family of PILOT_REGISTRY.diagnosisFamilies) {
      const concepts = PILOT_REGISTRY.concepts.filter((concept) =>
        concept.diagnosisFamilyIds.includes(family.id),
      );
      expect(concepts.length).toBeGreaterThanOrEqual(3);
      for (const concept of concepts) {
        expect(concept.questionVariants.length).toBeGreaterThanOrEqual(2);
        expect(
          new Set(concept.questionVariants.map((variant) => variant.stem)).size,
        ).toBe(concept.questionVariants.length);
      }
    }
  });

  it("projects exactly one primary concept per decision and respects tier decision limits", () => {
    for (const template of PILOT_REGISTRY.encounterTemplates) {
      const phenotype = PILOT_REGISTRY.phenotypes.find(
        (candidate) => candidate.id === template.phenotypeId,
      )!;
      const generated = materializePilotEncounter(
        PILOT_REGISTRY,
        template.id,
        `decision-test|${template.id}`,
      );
      const nodes = generated.clinicalCase.decisionNodes;

      expect(
        nodes.every(
          (node) =>
            typeof node.primaryConceptId === "string" &&
            node.primaryConceptId.length > 0,
        ),
      ).toBe(true);
      expect(new Set(nodes.map((node) => node.primaryConceptId)).size).toBe(
        nodes.length,
      );
      if (phenotype.educationalTier === 0) {
        expect(nodes).toHaveLength(1);
      } else {
        expect(nodes.length).toBeLessThanOrEqual(2);
      }
    }
  });

  it("generates compatible adult patients without meaningful comorbidity", () => {
    for (const generated of generatedForEveryTemplate()) {
      const { generatedPatient: patient, phenotype } = generated;
      const overlay = PILOT_REGISTRY.physiologyOverlays.find(
        (candidate) => candidate.id === patient.physiologyOverlayId,
      )!;
      const required = new Set([
        ...phenotype.requiredFindings,
        ...overlay.requiredFindings,
      ]);
      const excluded = new Set([
        ...phenotype.excludedFindings,
        ...overlay.excludedFindings,
      ]);

      expect(patient.ageYears).toBeGreaterThanOrEqual(18);
      expect(patient.comorbidities).toEqual([]);
      for (const finding of required) {
        expect(patient.findings).toContain(finding);
      }
      for (const finding of excluded) {
        expect(patient.findings).not.toContain(finding);
      }
    }
  });

  it("draws every vital sign from the assigned physiology overlay", () => {
    for (const generated of generatedForEveryTemplate("vital-range-test")) {
      const patient = generated.generatedPatient;
      const overlay = PILOT_REGISTRY.physiologyOverlays.find(
        (candidate) => candidate.id === patient.physiologyOverlayId,
      )!;
      const vitals = patient.vitalSigns;
      const within = (
        value: number,
        range: { minimum: number; maximum: number },
      ) => value >= range.minimum && value <= range.maximum;

      expect(
        within(vitals.heartRateBpm, overlay.vitalRanges.heartRateBpm),
      ).toBe(true);
      expect(
        within(
          vitals.systolicBloodPressureMmHg,
          overlay.vitalRanges.systolicBloodPressureMmHg,
        ),
      ).toBe(true);
      expect(
        within(
          vitals.diastolicBloodPressureMmHg,
          overlay.vitalRanges.diastolicBloodPressureMmHg,
        ),
      ).toBe(true);
      expect(
        within(vitals.temperatureF, overlay.vitalRanges.temperatureF),
      ).toBe(true);
      expect(
        within(
          vitals.oxygenSaturationPercent,
          overlay.vitalRanges.oxygenSaturationPercent,
        ),
      ).toBe(true);
      expect(vitals.diastolicBloodPressureMmHg).toBeLessThan(
        vitals.systolicBloodPressureMmHg,
      );
    }
  });

  it("varies paired pressures without imposing one fixed pulse pressure", () => {
    const pulsePressures = new Set(
      Array.from({ length: 40 }, (_, index) => {
        const vitals = materializePilotEncounter(
          PILOT_REGISTRY,
          "case.pilot.appendicitis-incomplete-multistep",
          `pressure-variation-${index}`,
        ).generatedPatient.vitalSigns;
        return (
          vitals.systolicBloodPressureMmHg -
          vitals.diastolicBloodPressureMmHg
        );
      }),
    );
    expect(pulsePressures.size).toBeGreaterThan(1);
  });

  it("uses qualitative optional-finding categories without numeric symptom rates", () => {
    for (const generated of generatedForEveryTemplate(
      "qualitative-finding-selection",
    )) {
      const overlay = PILOT_REGISTRY.physiologyOverlays.find(
        (candidate) =>
          candidate.id === generated.generatedPatient.physiologyOverlayId,
      )!;
      const required = new Set([
        ...generated.phenotype.requiredFindings,
        ...overlay.requiredFindings,
      ]);
      const renderedOptional = generated.generatedPatient.findings.filter(
        (finding) => !required.has(finding),
      );
      expect(renderedOptional.length).toBeLessThanOrEqual(1);
    }

    const urgentHernia = PILOT_REGISTRY.phenotypes.find(
      (phenotype) =>
        phenotype.id ===
        "phenotype.inguinal-hernia.l1-acutely-irreducible",
    )!;
    const urgentHerniaOverlay = PILOT_REGISTRY.physiologyOverlays.find(
      (overlay) =>
        overlay.id === urgentHernia.physiologyOverlayIds[0],
    )!;
    const required = new Set([
      ...urgentHernia.requiredFindings,
      ...urgentHerniaOverlay.requiredFindings,
    ]);
    const renderedAcrossSeeds = new Set(
      Array.from({ length: 100 }, (_, index) =>
        materializePilotEncounter(
          PILOT_REGISTRY,
          "case.pilot.inguinal-hernia-acute-transfer",
          `qualitative-category-${index}`,
        ).generatedPatient.findings.find((finding) => !required.has(finding)),
      ).filter((finding): finding is string => finding !== undefined),
    );
    expect(
      urgentHernia.commonOptionalFindings.some((finding) =>
        renderedAcrossSeeds.has(finding),
      ),
    ).toBe(true);
    expect(
      urgentHernia.possibleFindings.some((finding) =>
        renderedAcrossSeeds.has(finding),
      ),
    ).toBe(true);
    expect(
      urgentHernia.uncommonFindings.some((finding) =>
        renderedAcrossSeeds.has(finding),
      ),
    ).toBe(true);
  });

  it("keeps source-limited teaching points within their authored evidence boundary", () => {
    const lacerationAssessment = PILOT_REGISTRY.claims.find(
      (claim) => claim.id === "claim.laceration.preclosure_assessment",
    )!;
    expect(lacerationAssessment.statement.toLowerCase()).not.toContain(
      "perfusion",
    );

    const deepLaceration = PILOT_REGISTRY.concepts.find(
      (concept) => concept.id === "concept.laceration.deep-structure-referral",
    )!;
    expect(deepLaceration.disposition).toBe("prompt_specialty_referral");
    expect(
      deepLaceration.questionVariants
        .map((variant) => variant.stem)
        .join(" ")
        .toLowerCase(),
    ).not.toContain("numbness");

    const abscess = PILOT_REGISTRY.concepts.find(
      (concept) => concept.id === "concept.prototype.abscess.primary-treatment",
    )!;
    expect(abscess.disposition).toBe("procedural_referral");
    expect(JSON.stringify(abscess).toLowerCase()).not.toContain("same-day");

    const biliaryRedFlags = PILOT_REGISTRY.concepts.find(
      (concept) => concept.id === "concept.cholelithiasis.red-flag-transfer",
    )!;
    expect(
      biliaryRedFlags.questionVariants
        .map((variant) => variant.stem)
        .join(" ")
        .toLowerCase(),
    ).not.toContain("guarding");

    const appendicitisRecognition = PILOT_REGISTRY.concepts.find(
      (concept) =>
        concept.id === "concept.appendicitis.incomplete-pattern-recognition",
    )!;
    expect(JSON.stringify(appendicitisRecognition).toLowerCase()).not.toContain(
      "primary concern",
    );
  });

  it("keeps generated findings observable and free of disposition or authoring cues", () => {
    const forbiddenCues = [
      "emergency transfer",
      "scored question",
      "no reassuring alternate",
      "incomplete classic pattern",
    ];
    for (const generated of generatedForEveryTemplate("cue-leak-test")) {
      const visibleText = [
        generated.clinicalCase.presentation,
        ...generated.generatedPatient.findings,
      ]
        .join(" ")
        .toLowerCase();
      for (const cue of forbiddenCues) {
        expect(visibleText).not.toContain(cue);
      }
    }

    const laceration = materializePilotEncounter(
      PILOT_REGISTRY,
      "case.prototype.tutorial-laceration",
      "preclosure-no-leak",
    );
    expect(
      laceration.generatedPatient.findings.join(" ").toLowerCase(),
    ).not.toContain("intact distal");
  });

  it("uses source-linked adult reference bounds for every physiology overlay", () => {
    for (const overlay of PILOT_REGISTRY.physiologyOverlays) {
      expect(overlay.evidenceClaimIds).toContain(
        "claim.physiology.resting_adult_ranges",
      );
      expect(overlay.evidenceClaimIds).toContain(
        "claim.physiology.oxygen_saturation_range",
      );
      expect(overlay.vitalRanges.heartRateBpm.minimum).toBeGreaterThanOrEqual(60);
      expect(overlay.vitalRanges.heartRateBpm.maximum).toBeLessThanOrEqual(100);
      expect(
        overlay.vitalRanges.systolicBloodPressureMmHg.minimum,
      ).toBeGreaterThanOrEqual(90);
      expect(
        overlay.vitalRanges.systolicBloodPressureMmHg.maximum,
      ).toBeLessThanOrEqual(120);
      expect(
        overlay.vitalRanges.diastolicBloodPressureMmHg.minimum,
      ).toBeGreaterThanOrEqual(60);
      expect(
        overlay.vitalRanges.diastolicBloodPressureMmHg.maximum,
      ).toBeLessThanOrEqual(80);
      expect(overlay.vitalRanges.temperatureF.minimum).toBeGreaterThanOrEqual(
        96.4,
      );
      expect(overlay.vitalRanges.temperatureF.maximum).toBeLessThanOrEqual(
        99.1,
      );
      expect(
        overlay.vitalRanges.oxygenSaturationPercent.minimum,
      ).toBeGreaterThanOrEqual(94);
      expect(
        overlay.vitalRanges.oxygenSaturationPercent.maximum,
      ).toBeLessThanOrEqual(98);
    }
  });

  it("never substitutes plain X-ray for biliary or appendicitis evaluation", () => {
    const relevantTemplates = PILOT_REGISTRY.encounterTemplates.filter(
      (template) =>
        template.diagnosisFamilyId === "symptomatic_cholelithiasis" ||
        template.diagnosisFamilyId === "acute_appendicitis",
    );
    for (const template of relevantTemplates) {
      const generated = materializePilotEncounter(
        PILOT_REGISTRY,
        template.id,
        `no-xray|${template.id}`,
      );
      for (const node of generated.clinicalCase.decisionNodes) {
        const correct = node.answerChoices.find((choice) => choice.isCorrect)!;
        expect(correct.serviceRequest?.serviceId).not.toBe("service.xray");
        expect(correct.label.toLowerCase()).not.toContain("plain x-ray");
        expect(correct.label.toLowerCase()).not.toContain("plain xray");
      }
    }
  });

  it("keeps one concept identity across wording variants", () => {
    for (const concept of PILOT_REGISTRY.concepts) {
      const applicableTemplate = PILOT_REGISTRY.encounterTemplates.find(
        (template) => template.scoredConceptIds.includes(concept.id),
      )!;
      const nodeConceptIds = concept.questionVariants.map((variant) => {
        const generated = materializePilotEncounter(
          PILOT_REGISTRY,
          applicableTemplate.id,
          `variant-history|${variant.id}`,
          {
            forcedQuestionVariantIdsByConceptId: {
              [concept.id]: variant.id,
            },
          },
        );
        return generated.clinicalCase.decisionNodes.find(
          (node) => node.questionVariantId === variant.id,
        )!.primaryConceptId;
      });
      expect(new Set(nodeConceptIds)).toEqual(new Set([concept.id]));
    }
  });

  it("links every atomic claim to real source metadata without placeholders", () => {
    const sourceIds = new Set(
      PILOT_REGISTRY.sources.map((source) => source.id),
    );
    for (const claim of PILOT_REGISTRY.claims) {
      expect(claim.sourceIds.length).toBeGreaterThan(0);
      expect(claim.sourceIds.every((sourceId) => sourceIds.has(sourceId))).toBe(
        true,
      );
    }
    for (const source of PILOT_REGISTRY.sources) {
      expect(source.officialUrl ?? source.doi).toBeTruthy();
      expect(source.reuseStatus.length).toBeGreaterThan(0);
      expect(source.completeCitation.toLowerCase()).not.toContain(
        "placeholder",
      );
      if (source.officialUrl) {
        expect(source.officialUrl).toMatch(/^https:\/\/\S+$/);
      }
    }
  });

  it("keeps every authored pilot record in AI-assisted clinician-review status", () => {
    const records = [
      ...PILOT_REGISTRY.sources,
      ...PILOT_REGISTRY.claims,
      ...PILOT_REGISTRY.physiologyOverlays,
      ...PILOT_REGISTRY.diagnosisFamilies,
      ...PILOT_REGISTRY.diagnosisFamilies.map(
        (family) => family.chartBackSummary,
      ),
      ...PILOT_REGISTRY.phenotypes,
      ...PILOT_REGISTRY.concepts,
      ...PILOT_REGISTRY.concepts.flatMap(
        (concept) => concept.questionVariants,
      ),
      ...PILOT_REGISTRY.encounterTemplates,
    ];
    expect(
      records.every(
        (record) =>
          record.reviewStatus === "needs_clinician_review" &&
          record.aiAssistedDrafting &&
          record.lastClinicianReview == null,
      ),
    ).toBe(true);
    expect(PILOT_CLINICAL_RELEASE.publicationStatus).toBe(
      "synthetic_unapproved_prototype",
    );
  });

  it("builds the correct completed-chart claim and citation view for every case", () => {
    for (const template of PILOT_REGISTRY.encounterTemplates) {
      const review = getPilotChartReviewByCaseId(template.id);
      expect(review?.diagnosisId).toBe(template.diagnosisFamilyId);
      expect(review?.sections.map((section) => section.heading)).toEqual([
        "What it is",
        "Typical presentation",
        "Initial evaluation",
        "Management in this clinic",
        "Red flags requiring urgent care",
      ]);
      expect(review?.sources.length).toBeGreaterThan(0);
      expect(
        review?.sources.every(
          (source) =>
            source.supportedClaimIds.length > 0 &&
            source.href.startsWith("https://"),
        ),
      ).toBe(true);
    }
  });

  it("deterministically previews every diagnosis and educational tier", () => {
    for (const family of PILOT_REGISTRY.diagnosisFamilies) {
      for (const educationalTier of [0, 1] as const) {
        const phenotypeIds = new Set(
          PILOT_REGISTRY.phenotypes
            .filter(
              (phenotype) =>
                phenotype.diagnosisFamilyId === family.id &&
                phenotype.educationalTier === educationalTier,
            )
            .map((phenotype) => phenotype.id),
        );
        const template = PILOT_REGISTRY.encounterTemplates.find(
          (candidate) =>
            candidate.diagnosisFamilyId === family.id &&
            phenotypeIds.has(candidate.phenotypeId),
        )!;
        const first = materializePilotEncounter(
          PILOT_REGISTRY,
          template.id,
          "deterministic-preview",
        );
        const second = materializePilotEncounter(
          PILOT_REGISTRY,
          template.id,
          "deterministic-preview",
        );
        expect(second).toEqual(first);
      }
    }
  });
});
